class Janela:
    def __init__(self, limite): self.limite, self.contagens = limite, {}
    def permitir(self, cliente, janela):
        chave = (cliente, janela)
        atual = self.contagens.get(chave, 0)
        if atual >= self.limite: return False
        self.contagens[chave] = atual + 1
        return True

